[{"role":"system","content":"You are grading output according to a user-specified rubric. If the statement in the rubric is true, then the output passes the test. You respond with a JSON object with this structure: {reason: string, pass: boolean, score: number}

Examples:

<Output>Hello world</Output>
<Rubric>Content contains a greeting</Rubric>
{"reason": "the content contains the word 'Hello'", "pass": true, "score": 1.0}

<Output>Avast ye swabs, repel the invaders!</Output>
<Rubric>Does not speak like a pirate</Rubric>
{"reason": "'avast ye' is a common pirate term", "pass": false, "score": 0.0}"},{"role":"user","content":"<Output>
{"world_id":"wld_seedways","characters":[{"id":"chr_maren_voss","name":"Maren Voss","role":"protagonist","description":"A weathered woman in her late forties, Maren is the lead seed-keeper of the caravan. She was raised in the terraced vaults of Granary Hill and has hauled sealed seed stock along the seedways for twenty-five years. Her hands are stained with grain-dust and her coat is patched with oilcloth. She carries a grading sieve of salvaged hand-forged wire that belonged to her mother.","home_location_id":"loc_granary_hill","faction_id":"fac_seed_keepers","motivation":"She wants to prove that the seedway circuit can still hold the valleys together, as her mother believed before she died on the road.","goal":"Carry the seed stock through all three towns and over the Frost Gate before the last frost, with the tithe fully honored.","flaw":"She distrusts anyone outside the keepers' order and assumes the worst of them before hearing them out.","internal_conflict":"She fears that the order's sworn purity of grain has made her rigid, yet loosening her grip feels like betraying her mother's memory.","external_conflict":"The Cut Grain accusation threatens to brand her caravan as the culprit, and the Frost Gate's closing leaves her little time to clear it.","arc":"Maren begins by treating every miller and orchard family as a suspect to be managed. At Ford Market she opens a sealed sack in front of the weigh-house and lets Tobin Hale test it publicly, accepting the risk that the fault lies with her own order. By the Frost Gate she shares the keepers' grading method with outsiders and trusts joint custody of the stock.","personality_traits":["stubborn","meticulous","dry-humored","protective","tired"],"abilities":[{"name":"Grain Grading","description":"Judges the purity and viability of seed stock by touch, smell and a hand sieve.","category":"mental"},{"name":"Long-Road Endurance","description":"Walks and drives a laden caravan for days on little rest in cold weather.","category":"physical"},{"name":"Vault Sealing","description":"Seals and verifies seed sacks with keeper wax and knotwork that shows any tampering.","category":"other"}]},{"id":"chr_tobin_hale","name":"Tobin Hale","role":"supporting","description":"A heavyset, soft-spoken miller in his fifties who keeps the tithe ledgers at the Ford Market weigh-house. His apron is always dusted with flour, and he wears brass-rimmed spectacles mended with twine. His father was a clerk during the Millers' Split, and the family has lived under that suspicion since.","home_location_id":"loc_ford_market","faction_id":"fac_millers_compact","motivation":"He wants to clear his family's name from the stain of the falsified ledger that caused the Millers' Split.","goal":"Find who is diluting tithe grain with chaff and show the Compact's books are honest.","flaw":"He hoards information and hides small ledger errors out of shame, which makes honest mistakes look like fraud.","internal_conflict":"He suspects that an old ledger entry in his own family's hand may be forged, but he fears learning the truth.","external_conflict":"The keepers accuse the Compact of the Cut Grain, and Compact elders pressure him to bury any discrepancy.","arc":"Tobin starts out concealing a ledger discrepancy he cannot explain. When Maren offers an open public test of her sacks, he brings the old ledger out of the locked chest and lays it before the market. He ends as the first miller to co-sign a joint tithe record with a keeper.","personality_traits":["cautious","kind","anxious","precise"],"abilities":[{"name":"Ledger Reading","description":"Spots altered figures and mismatched hands in tithe records.","category":"mental"},{"name":"Weigh-House Authority","description":"His seal on a weighing is accepted by the market's traders.","category":"social"}]},{"id":"chr_sorrel_ashby","name":"Sorrel Ashby","role":"supporting","description":"A lean, sun-browned woman in her thirties who leads a planting family on the Ash Orchards' worst rows. Her fingers are scarred from grafting knives, and she wears a hat woven from orchard-pruning willow. Her family took the blight-ash land first and has waited years for promised grafting stock.","home_location_id":"loc_ash_orchards","faction_id":"fac_orchard_families","motivation":"She wants her children to inherit living orchards instead of failing rows.","goal":"Secure the grafting stock the vaults promised the orchard families before the frost closes the pass.","flaw":"She is quick to act on grievance and will take what she believes she is owed without asking.","internal_conflict":"She knows the tithe is fair, but resents repaying two measures when the ash soil yields so little.","external_conflict":"She believes the caravan is carrying her promised grain elsewhere, and her neighbors urge her to stop it by force.","arc":"Sorrel begins by planning to block the caravan's wagons at the orchard road. After Maren shows her the sealed ledger of what was actually allotted, she chooses to stand down her neighbors and instead negotiate a staged delivery. She ends by hosting the caravan overnight and offering her own grafts as security for the tithe.","personality_traits":["fierce","practical","proud","loyal"],"abilities":[{"name":"Grafting","description":"Joins cuttings to rootstock so poor soil can bear fruit.","category":"physical"},{"name":"Rallying Neighbors","description":"Persuades the orchard families to act together.","category":"social"}]},{"id":"chr_edric_cole","name":"Edric Cole","role":"antagonist","description":"A smooth-voiced keeper in his early forties who rides as Maren's quartermaster. He is tall, neatly bearded, and always seems to carry the caravan's accounts. He has been quietly cutting seed stock with chaff and selling the surplus grain to desperate towns off the books.","home_location_id":"loc_granary_hill","faction_id":"fac_seed_keepers","motivation":"He wants to buy a place for himself in a town with safe granaries, so he never winters alone on the road.","goal":"Keep the dilution hidden through the circuit and pin the Cut Grain on the Millers' Compact.","flaw":"He believes his own lies are justified by need, and he grows careless whenever he feels cornered.","internal_conflict":"He cannot reconcile his oath to the keepers with his belief that the order will let the valleys starve.","external_conflict":"Maren's public testing threatens to expose him, and the keepers' rule strikes adulterers from the rolls.","arc":"Edric begins by deflecting suspicion with small, plausible accusations toward the Compact. When Maren proposes the open sack test at Ford Market, he tries to switch a sack and is caught by Tobin's weigh-house seal. He ends struck from the rolls, his name never to be carried again.","personality_traits":["charming","calculating","anxious","resentful"],"abilities":[{"name":"Persuasion","description":"Makes accusations sound like reasonable concern.","category":"social"},{"name":"Account Juggling","description":"Hides losses by shifting numbers between caravan and vault tallies.","category":"mental"}]},{"id":"chr_wren_tally","name":"Wren Tally","role":"supporting","description":"A sixteen-year-old apprentice keeper with a gap-toothed grin and an oversized coat inherited from a dead cousin. Orphaned in the last hard winter, she was taken in by the order and assigned to Maren's wagon. She keeps a notched stick to count every sack.","home_location_id":"loc_granary_hill","faction_id":"fac_seed_keepers","motivation":"She wants to belong to something that will not abandon her, and the order is the only home she has.","goal":"Earn her keeper's knot by completing the circuit without losing a single sack.","flaw":"She is overeager to please and keeps quiet when she notices something wrong.","internal_conflict":"She admires Edric, who taught her to count, yet her tally stick keeps disagreeing with his totals.","external_conflict":"Edric pressures her to accept his numbers while Maren expects her to speak up about errors.","arc":"Wren begins by hiding the mismatch between her tally and Edric's, afraid of losing her place. Before the Frost Gate she brings the notched stick to Maren and testifies against him. She ends as a keeper who speaks first when the count is wrong.","personality_traits":["earnest","observant","anxious","quick-witted"],"abilities":[{"name":"Tally Notching","description":"Keeps exact running counts on a notched stick without error.","category":"mental"},{"name":"Light-Footed Scouting","description":"Moves quietly and scouts ahead of the caravan on narrow trails.","category":"physical"}]}],"relationships":[{"id":"rel_maren_edric_suspicion","source_character_id":"chr_maren_voss","target_character_id":"chr_edric_cole","relationship_type":"ally","description":"Maren Voss trusts her quartermaster Edric Cole as a fellow keeper and relies on his accounts, which blinds her to his dilution of the stock and deepens the Cut Grain feud."},{"id":"rel_edric_tobin_blame","source_character_id":"chr_edric_cole","target_character_id":"chr_tobin_hale","relationship_type":"enemy","description":"Edric Cole steers blame for the Cut Grain toward Tobin Hale and the Millers' Compact, inflaming the old distrust between keepers and millers."},{"id":"rel_maren_tobin_distrust","source_character_id":"chr_maren_voss","target_character_id":"chr_tobin_hale","relationship_type":"rival","description":"Maren Voss and Tobin Hale begin as wary rivals over the weigh-house ledgers, each assuming the other's order is cheating the tithe, before they slowly become partners."},{"id":"rel_sorrel_maren_claim","source_character_id":"chr_sorrel_ashby","target_character_id":"chr_maren_voss","relationship_type":"rival","description":"Sorrel Ashby accuses Maren Voss of carrying the orchard families' promised grafting stock away, threatening to block the caravan on the orchard road."},{"id":"rel_maren_wren_mentor","source_character_id":"chr_maren_voss","target_character_id":"chr_wren_tally","relationship_type":"mentor","description":"Maren Voss mentors her apprentice Wren Tally, pressing her to speak up about errors, which collides with Wren's loyalty to Edric."},{"id":"rel_wren_edric_loyalty","source_character_id":"chr_wren_tally","target_character_id":"chr_edric_cole","relationship_type":"friend","description":"Wren Tally admires Edric Cole, who taught her to count, and her loyalty makes her hide the mismatch between her tally stick and his totals."}]}
